// Actual C3 read-only status aggregation. No provider is probed and no memory store is opened.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,readdirSync} from 'node:fs';
import path from 'node:path';import {pathToFileURL} from 'node:url';
const root=process.env.PLUR1BUS_ENGINE_SRC;assert.ok(root);assert.equal(process.version,'v24.21.0');
const source=JSON.parse(readFileSync(new URL('./guards-sources.json',import.meta.url),'utf8'));
const files=[];function walk(dir){for(const e of readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else if(e.name.endsWith('.js'))files.push(f);}}
walk(path.join(root,'engine'));walk(path.join(root,'lib'));const hash=createHash('sha256');for(const f of files.sort()){hash.update(`${path.relative(root,f)}\0`);hash.update(readFileSync(f));hash.update('\0');}assert.equal(hash.digest('hex'),source.treeSha256);
const load=f=>import(pathToFileURL(path.join(root,f)));
const {validateMemoryStoreParams,resolveTtlMs}=await load('lib/input-limits.js');
const {MEMORY_CATEGORIES}=await load('lib/categorize.js');const {mergedExpiresAt,isManualCoreMarker}=await load('lib/memory-dynamics.js');
const {createMemoryTools}=await load('engine/tools/memory-tools.js');
const value=v=>v?.tag==='undefined'?undefined:v?.tag==='nan'?NaN:v?.tag==='infinity'?Infinity:v?.tag==='negative-infinity'?-Infinity:v;
const storeDefs=[{},...['', ' ', '\ufeff\u00a0', '\u0085', 'synthetic',0,false,null,[],{}].map(text=>({text})),...MEMORY_CATEGORIES.map(category=>({text:'synthetic',category})),...['','FACT','unknown',0,false,null,[],{}].map(category=>({text:'synthetic',category}))];
const lengths=[{unit:'x',count:50000},{unit:'x',count:50001},{unit:'😀',count:25000},{unit:'😀',count:25001}];
const ttlMap={session:86400000,short:1209600000,zero:0,negative:-1,string:'12',bad:'bad'};
const values=[{tag:'undefined'},null,false,true,0,-1,1,5000,9000,'0','5000','0x10','bad','',[],[12],[1,2],{}, {tag:'nan'},{tag:'infinity'},{tag:'negative-infinity'}];
function context(def,calls){const entry={id:'11111111-1111-4111-8111-111111111111',agentId:'agent',text:'Synthetic visible candidate',scope:'agent-private',status:'active'};const scores=def.scores.map(value);return{cfg:{security:{allowModelDestructiveMemoryOps:!def.disabled}},workspacePolicyGuard:{decision:()=>({allowed:true})},forgetThreshold:value(def.threshold),pool:{withWriteDb:async(_agent,fn)=>{calls.open++;return fn({search:async()=>scores.map((score,i)=>({score,entry:{...entry,id:`11111111-1111-4111-8111-${String(i+1).padStart(12,'0')}`}})),searchDeleted:async()=>[],getById:async id=>({...entry,id,status:'deleted'})});}},embeddings:{embedQuery:async()=>{calls.embed++;return[1,0,0,0]}},tombstoneMemoryWithAudit:async()=>{calls.forget++},host:{logger:{warn(){}}},dbg(){}};}
const forgetDefs=[];for(const threshold of [.3,.75,.9,{tag:'nan'},{tag:'infinity'},'0.9'])for(const scores of [[],[.333],[.7499],[.75],[.9],[1],[.99,.99],[{tag:'nan'}]])forgetDefs.push({threshold,scores});forgetDefs.push({threshold:.3,scores:[1],disabled:true});
async function record(){const store=storeDefs.map(params=>({params,result:validateMemoryStoreParams(params,{categories:MEMORY_CATEGORIES})}));for(const repeat of lengths)store.push({repeat,result:validateMemoryStoreParams({text:repeat.unit.repeat(repeat.count)},{categories:MEMORY_CATEGORIES})});
const ttl=[...Object.keys(ttlMap),'constructor','toString','__proto__','unknown',null,0,{},[]].map(input=>({input,result:resolveTtlMs(ttlMap,input)}));
const merge=[];for(const a of values)for(const b of values)merge.push({a,b,result:mergedExpiresAt(value(a),value(b))});
const expiry=[];for(const importance of [.9,.949999,.95,.97,1])for(const ttl of [0,86400000,1209600000,-1]){const expires=ttl>0?1800000000000+ttl:0;expiry.push({importance,ttl,result:expires>0&&isManualCoreMarker({importance})?{reason:'ttl_conflicts_with_core_importance'}:{expiresAt:expires}});}
const forget=[];for(const d of forgetDefs){const calls={open:0,embed:0,forget:0};const tool=createMemoryTools(context(d,calls))({agentId:'agent',workspaceDir:'/tmp'}).find(t=>t.name==='memory_forget');const result=await tool.execute('synthetic-call',{query:'synthetic query'});const text=result.content[0].text;assert.ok(d.disabled||/^(Found |Forgotten|No matching)/.test(text),text);const decision=d.disabled?'blocked':calls.forget?'forget':text.startsWith('No matching')?'none':'confirm';forget.push({...d,result,decision,calls});}const storeTool=[];for(const importance of [.95,.97,1])for(const ttl of ['session','short']){let embedded=0;const ctx={...context({scores:[],threshold:.3},{open:0,embed:0,forget:0}),TTL_MAP:ttlMap,traceCfg:{},resolveStoreScopeAccess:()=>({ok:true,scope:'agent-private',ownershipFields:{agentId:'agent',scope:'agent-private'}}),embeddings:{embed:async()=>{embedded++;return[1,0,0,0]}}};const tool=createMemoryTools(ctx)({agentId:'agent',workspaceDir:'/tmp'}).find(t=>t.name==='memory_store');const result=await tool.execute('synthetic-call',{text:'Synthetic fact about storage',category:'fact',importance,ttl});assert.equal(result.details?.reason,'ttl_conflicts_with_core_importance',JSON.stringify(result));storeTool.push({importance,ttl,result,embedded});}return{store,ttlMap,ttl,merge,expiry,forget,storeTool};}
const cases=await record();assert.deepEqual(await record(),cases);writeFileSync(new URL('./golden/guards.json',import.meta.url),JSON.stringify({recordedFrom:{source,node:process.version},...cases},null,2)+'\n');console.log(`Recorded ${cases.store.length} store, ${cases.ttl.length} TTL, ${cases.merge.length} merge, ${cases.expiry.length} expiry and ${cases.forget.length} actual tool-forget and ${cases.storeTool.length} actual core-TTL tool cases twice`);
